import React, { useState, useEffect, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import { getAcompanhamento } from '../../services/mesaAcompanharService';
import { formatDuracao } from '../../utils/formatDuracao';
import { useNowTick } from '../../hooks/useNowTick';
import Icon from '../../components/AppIcon';

const STATUS_ITEM_LABEL = { pendente: 'Anotado', enviado: 'Em preparo', pronto: 'Pronto' };
const STATUS_COMANDA_LABEL = {
  aberta: 'Em andamento',
  fechada_garcom: 'Aguardando pagamento no caixa',
  paga: 'Pago — obrigado!',
  canceled: 'Cancelada',
};

const MesaAcompanhar = () => {
  const { token } = useParams();
  const [dados, setDados] = useState(null);
  const [erro, setErro] = useState(null);
  const now = useNowTick();

  const carregar = useCallback(async () => {
    try {
      const d = await getAcompanhamento(token);
      setDados(d);
      setErro(null);
    } catch (err) {
      setErro(err.message ?? 'Não foi possível carregar.');
    }
  }, [token]);

  useEffect(() => {
    carregar();
    const interval = setInterval(carregar, 15000);
    return () => clearInterval(interval);
  }, [carregar]);

  if (erro) return <div className="min-h-screen flex items-center justify-center p-6 text-sm text-red-600">{erro}</div>;
  if (!dados) return <div className="min-h-screen flex items-center justify-center text-sm text-[#71717A]">Carregando...</div>;

  return (
    <div className="min-h-screen bg-[#F4F4F5] p-4 flex flex-col items-center">
      <div className="w-full max-w-sm">
        <div className="text-center mb-4 mt-4">
          <div className="w-14 h-14 bg-[#FF441F]/10 rounded-2xl flex items-center justify-center mx-auto mb-2">
            <Icon name="UtensilsCrossed" size={26} className="text-[#FF441F]" />
          </div>
          <h1 className="text-lg font-black text-[#18181B]">{dados.restaurante}</h1>
          {dados.mesa && <p className="text-sm text-[#71717A]">{dados.mesa}</p>}
        </div>

        <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4 mb-3 text-center">
          <p className="text-xs text-[#71717A]">Status</p>
          <p className="text-base font-bold text-[#18181B]">{STATUS_COMANDA_LABEL[dados.status] ?? dados.status}</p>
        </div>

        <div className="space-y-2">
          {dados.itens.map((item, i) => {
            const enviadoEm = item.enviado_em ? new Date(item.enviado_em).getTime() : null;
            const tempoPreparo = enviadoEm ? now - enviadoEm : null;
            return (
              <div key={i} className="bg-white rounded-xl border border-[#E4E4E7] p-3">
                <div className="flex justify-between items-center">
                  <span className="text-sm text-[#18181B]">{item.quantity}x {item.product_name}</span>
                  <span className={`text-[10px] px-2 py-1 rounded-full font-medium ${
                    item.status === 'pronto' ? 'bg-emerald-100 text-emerald-700' : item.status === 'enviado' ? 'bg-orange-100 text-orange-700' : 'bg-zinc-100 text-zinc-600'
                  }`}>
                    {STATUS_ITEM_LABEL[item.status] ?? item.status}
                  </span>
                </div>
                {enviadoEm && item.status !== 'pronto' && (
                  <p className="text-[11px] text-[#71717A] font-mono mt-1 flex items-center gap-1">
                    <Icon name="Clock" size={11} /> preparando há {formatDuracao(tempoPreparo)}
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default MesaAcompanhar;

import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const OrderActions = ({
  orderStatus = 'confirmed',
  orderId = '#12345',
  onCancelOrder = () => {},
  onReorder = () => {},
  primaryColor = '#2563EB',
  isPago = false,
  valorDevolver = 0,
  className = ''
}) => {
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [cancelReason, setCancelReason] = useState('');
  const [loading, setLoading] = useState(false);

  const canCancel = ['pending', 'confirmed'].includes(orderStatus);
  const canReorder = orderStatus === 'delivered';

  const cancelReasons = [
    'Mudei de ideia',
    'Demora na entrega',
    'Erro no pedido',
    'Problema com pagamento',
    'Outro motivo'
  ];

  const handleCancelClick = () => {
    setShowCancelModal(true);
  };

  const handleConfirmCancel = async () => {
    if (!cancelReason) return;
    setLoading(true);
    try {
      await onCancelOrder({ orderId, reason: cancelReason });
      setShowCancelModal(false);
    } catch (error) {
      console.error('Error canceling order:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleReorderClick = () => {
    onReorder(orderId);
  };

  const handleBackdropClick = (e) => {
    if (e?.target === e?.currentTarget) {
      setShowCancelModal(false);
    }
  };

  return (
    <>
      <div className={`bg-card rounded-lg border border-border p-6 ${className}`}>
        <h3 className="font-medium text-foreground mb-4">Ações do Pedido</h3>

        <div className="space-y-3">
          {canReorder && (
            <Button
              onClick={handleReorderClick}
              variant="default"
              fullWidth
              iconName="RotateCcw"
              iconPosition="left"
              style={{ backgroundColor: primaryColor }}
            >
              Pedir Novamente
            </Button>
          )}

          {canCancel && (
            <Button
              onClick={handleCancelClick}
              variant="outline"
              fullWidth
              iconName="X"
              iconPosition="left"
            >
              Cancelar Pedido
            </Button>
          )}

          <Button
            variant="ghost"
            fullWidth
            iconName="Download"
            iconPosition="left"
          >
            Baixar Recibo
          </Button>

          <Button
            variant="ghost"
            fullWidth
            iconName="Share2"
            iconPosition="left"
          >
            Compartilhar Pedido
          </Button>
        </div>

        {orderStatus === 'delivered' && (
          <div className="mt-6 pt-4 border-t border-border">
            <h4 className="font-medium text-foreground mb-3">Avalie seu pedido</h4>
            <div className="flex items-center space-x-2 mb-3">
              {[1, 2, 3, 4, 5]?.map((star) => (
                <button
                  key={star}
                  className="p-1 hover:scale-110 transition-transform duration-200"
                >
                  <Icon 
                    name="Star" 
                    size={20} 
                    className="text-muted-foreground hover:text-yellow-400 transition-colors duration-200" 
                  />
                </button>
              ))}
            </div>
            <Button
              variant="outline"
              fullWidth
              iconName="MessageSquare"
              iconPosition="left"
            >
              Deixar Comentário
            </Button>
          </div>
        )}
      </div>
      {/* Cancel Order Modal */}
      {showCancelModal && (
        <div 
          className="fixed inset-0 z-200 flex items-center justify-center p-4 bg-black bg-opacity-50 animate-fade-in"
          onClick={handleBackdropClick}
        >
          <div className="w-full max-w-md bg-card rounded-lg shadow-lg animate-slide-up elevation-3 max-h-[90vh] overflow-y-auto">
            {/* Header */}
            <div className="flex items-center justify-between p-6 border-b border-border">
              <h3 className="text-lg font-semibold text-foreground">
                Cancelar Pedido
              </h3>
              <button
                onClick={() => setShowCancelModal(false)}
                className="p-1 rounded-lg hover:bg-muted transition-colors duration-200"
              >
                <Icon name="X" size={20} className="text-muted-foreground" />
              </button>
            </div>

            {/* Content */}
            <div className="p-6">
              <div className="mb-4">
                <p className="text-sm text-muted-foreground mb-4">
                  Tem certeza que deseja cancelar o pedido {orderId}? 
                  Por favor, selecione o motivo do cancelamento:
                </p>

                <div className="space-y-2">
                  {cancelReasons?.map((reason) => (
                    <label
                      key={reason}
                      className="flex items-center space-x-3 p-3 rounded-lg border border-border hover:bg-muted cursor-pointer transition-colors duration-200"
                    >
                      <input
                        type="radio"
                        name="cancelReason"
                        value={reason}
                        checked={cancelReason === reason}
                        onChange={(e) => setCancelReason(e?.target?.value)}
                        className="w-4 h-4"
                        style={{ accentColor: primaryColor }}
                      />
                      <span className="text-sm text-foreground">{reason}</span>
                    </label>
                  ))}
                </div>
              </div>

              {isPago && valorDevolver > 0 && (
                <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg flex items-start gap-2">
                  <Icon name="RefreshCw" size={16} className="text-blue-600 flex-shrink-0 mt-0.5" />
                  <p className="text-sm text-blue-800">
                    Valor a devolver:{' '}
                    <strong>
                      {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(valorDevolver)}
                    </strong>
                    <span className="block text-xs text-blue-600 mt-0.5">
                      O estorno será processado pelo restaurante.
                    </span>
                  </p>
                </div>
              )}

              <div className="flex space-x-3">
                <Button
                  onClick={() => setShowCancelModal(false)}
                  variant="outline"
                  fullWidth
                >
                  Manter Pedido
                </Button>
                <Button
                  onClick={handleConfirmCancel}
                  variant="destructive"
                  fullWidth
                  loading={loading}
                  disabled={!cancelReason}
                >
                  Confirmar Cancelamento
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default OrderActions;

